Q3: Arithmetic Expressions with PEG [6 points]
PEG grammar:

S ← E
E ← T (&#039;+&#039; T)*
T ← F (&#039;×&#039; F)*
F ← P&#039;²&#039; / P
P ← &#039;a&#039; / &#039;(&#039; E &#039;)&#039;


class Backtrack:
  src: str

  def literal(self, k: int, a: str):
    if self.src.startswith(a, k):
      return k + len(a)

  def S(self, k):
    return self.E(k)

  def E(self, k):
    k = self.T(k)
    if k is None:
      return None
    while True:
      r = self.literal(k, &#039;+&#039;)
      if r is None:
        return k
      r = self.T(r)
      if r is None:
        return k
      k = r

  def T(self, k):
    k = self.F(k)
    if k is None:
      return None
    while True:
      r = self.literal(k, &#039;×&#039;)
      if r is None:
        return k
      r = self.F(r)
      if r is None:
        return k
      k = r

  def F(self, k):
    r = self.P(k)
    if r is not None:
      s = self.literal(r, &#039;²&#039;)
      if s is not None:
        return s
      return r
    return None

  def P(self, k):
    r = self.literal(k, &#039;a&#039;)
    if r is not None:
      return r
    r = self.literal(k, &#039;(&#039;)
    if r is not None:
      r = self.E(r)
      if r is not None:
        r = self.literal(r, &#039;)&#039;)
        return r
    return None

  def parse(self, s: str):
    self.src = s
    return self.S(0) == len(s)

