Part 1: Backtracking parser

class StatementBacktrack:
  src: str

  def literal(self, k: int, a: str):
    if self.src.startswith(a, k):
      return k + len(a)

  def ident(self, k):
    if k &lt; len(self.src) and &#039;a&#039; &lt;= self.src[k] &lt;= &#039;z&#039;:
      return k + 1
    return None

  def selector(self, k):
    while True:
      r = self.literal(k, &#039;[&#039;)
      if r is not None:
        r = self.ident(r)
        if r is not None:
          r = self.literal(r, &#039;]&#039;)
          if r is not None:
            k = r
            continue
      r = self.literal(k, &#039;.&#039;)
      if r is not None:
        r = self.ident(r)
        if r is not None:
          k = r
          continue
      return k

